window.RP_SESSION={"id":"S-4c469e232ea3","messages":[{"id":"RP-0242878","time":"2026-08-20T18:33:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"일주일, 길어야 이주일.","characters":["P-7ba611cf90be"]},{"id":"RP-0242879","time":"2026-08-20T18:33:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"솔직히 그 안에 유의미한 체력 증진 자체를 기대하지는 않는다.","characters":["P-7ba611cf90be"]},{"id":"RP-0242880","time":"2026-08-20T18:33:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"다만 자신의 체력의 한계를 아는 것.","characters":["P-7ba611cf90be"]},{"id":"RP-0242881","time":"2026-08-20T18:34:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"끝의 끝의 끝의 끝을 찍어보는 것.","characters":["P-7ba611cf90be"]},{"id":"RP-0242882","time":"2026-08-20T18:34:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"그것이 전장에서 생사를 결정하는 '마지막 한 걸음 더'를 판단하게 해줄 것이다.","characters":["P-7ba611cf90be"]},{"id":"RP-0242883","time":"2026-08-20T18:35:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"그것이 악으로 쥐어짜내고 쓰러지기 위한 무모한 걸음인지를.","characters":["P-7ba611cf90be"]},{"id":"RP-0242884","time":"2026-08-20T18:36:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"그것이 더 뛸 수 있었음에도 포기해버려 포탄을 맞을 거짓된 한계인지를.","characters":["P-7ba611cf90be"]},{"id":"RP-0242885","time":"2026-08-20T18:36:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"노오력이 부족해서 그런 거야 따위의 꼰대같은 이야기는 여기까지.","characters":["P-7ba611cf90be"]},{"id":"RP-0242886","time":"2026-08-20T18:38:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"실질적인 훈련.\n\n장애물을 뛰어넘는 방법이나 포를 쏘는 방법이나 배에서 싸우는 법 등의 실전적인 이야기를 해야했다.","characters":["P-7ba611cf90be"]},{"id":"RP-0242887","time":"2026-08-20T18:39:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"당연히 진지 공사에도 인력이 필요했기에 겨우 일주일 남짓한 훈련을 위해 훈련장을 만들어낼 순 없었다.","characters":["P-7ba611cf90be"]},{"id":"RP-0242888","time":"2026-08-20T18:41:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"또한 토르번에게 해상전 경력은 이번 한 번이 끝이었기에, 해돋이 사나이들의 자문을 받아 해변과 뒷산 절벽이 통나무 등으로 단순한 장애물들을 배치해 간이 훈련장을 만들었다.","characters":["P-7ba611cf90be"]},{"id":"RP-0242889","time":"2026-08-20T18:43:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"거기 넘어진 놈! 바로 일어나서 뒷줄에 붙어라! 적은 걸려 넘어졌다고 다시 자세를 잡을 시간 따위는 안 준다!\"","characters":["P-7ba611cf90be"]},{"id":"RP-0242890","time":"2026-08-20T18:43:00+09:00","room":"RP","name":"마을 주민들","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"어제는 팔 넷 달린 괴인이 우릴 패고, 오늘은 북부 놈이 우릴 패는구나야!\"","characters":[]},{"id":"RP-0242891","time":"2026-08-20T18:44:00+09:00","room":"RP","name":"마을 주민들","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"그러게요, 행님!\"","characters":[]},{"id":"RP-0242892","time":"2026-08-20T18:44:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...오호라.\"\n\n\"훈련에 불만 있는가?\"","characters":["P-7ba611cf90be"]},{"id":"RP-0242893","time":"2026-08-20T18:45:00+09:00","room":"RP","name":"마을 주민들","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"에구, 아니야, 아니야.\"","characters":[]},{"id":"RP-0242894","time":"2026-08-20T18:47:00+09:00","room":"RP","name":"마을 주민들","profile":"델타인","identity":"reviewed","type":"dialogue","body":"어제 페트라에게 후드려 맞은 그 듀오가 다시 일어섰습니다.","characters":[]},{"id":"RP-0242895","time":"2026-08-20T18:47:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"강도 높은 훈련에 불만 가지는 건 이해하는 바이다.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0242896","time":"2026-08-20T18:47:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"허나 우리에게 얻어맞고 장애물을 넘다가 자빠지는 것이 아프겠나?\"","characters":["P-7ba611cf90be"]},{"id":"RP-0242897","time":"2026-08-20T18:48:00+09:00","room":"RP","name":"마을 주민들","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"아니, 고건 아는디요! 여기 설치하는 일도 우리가 했걸랑요!\"","characters":[]},{"id":"RP-0242898","time":"2026-08-20T18:49:00+09:00","room":"RP","name":"마을 주민들","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"피곤하다 이거죠!\"","characters":[]},{"id":"RP-0242899","time":"2026-08-20T18:49:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"시간이 일주일 밖에 없...!\"\n\n그는 말문이 막힌 듯 머릴 긁적였다.","characters":["P-7ba611cf90be"]},{"id":"RP-0242900","time":"2026-08-20T18:51:00+09:00","room":"RP","name":"마을 주민들","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"인제 1일차인데 아침에 요거 맨들구, 점심에도 언덕까지 뛰어갔다 내려오구, 저녁에도 이카믄 우린 언제 쉽니까!\"","characters":[]},{"id":"RP-0242901","time":"2026-08-20T18:56:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"그래. 쉬게나. 이 정도가 힘들고 아파서 못 견디겠다면 쉬게나.\"\n\n\"헌데 이 훈련이 해적들에게 채찍맞으며 노역 당하는 것보다 힘들겠나?\"\n\n\"아니면 그들이 자네들의 아내와 딸들을 강제로 데려갈 때의 마음보다 아프겠나?!\"\n\n\"아니면 자네들의 아들이 해적이 되어 남들을 약탈하는 꼴을 보는 것보다 더 아프겠나!!!\"","characters":["P-7ba611cf90be"]},{"id":"RP-0242902","time":"2026-08-20T18:56:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"좋아. 그럼에도 힘들다면 해산하고 저녁에는 자원하는 자들만 남게.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0242903","time":"2026-08-20T19:00:00+09:00","room":"RP","name":"마을 주민들","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"예라이, 얼굴에 칼질한 양반이 말은 청산유수네.\"","characters":[]},{"id":"RP-0242904","time":"2026-08-20T19:01:00+09:00","room":"RP","name":"마을 주민들","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"행님, 저분도 은근히 배운 사람인가봐요. 행님도 다라이는 아귀 같은데 언변은 좋으시잖습니까.\"","characters":[]},{"id":"RP-0242905","time":"2026-08-20T19:01:00+09:00","room":"RP","name":"마을 주민들","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"해적 놈들 전에 너부터 쪼사줄까?\"","characters":[]},{"id":"RP-0242906","time":"2026-08-20T19:02:00+09:00","room":"RP","name":"마을 주민들","profile":"델타인","identity":"reviewed","type":"dialogue","body":"토르번, 매력+3!","characters":[]},{"id":"RP-0242907","time":"2026-08-20T19:02:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"!매력+3","characters":["P-7ba611cf90be"]},{"id":"RP-0242908","time":"2026-08-20T19:02:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'토르번 팔켄하인'의 매력 판정 :\n[6] + [-1] + [3] = [8]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-0242909","time":"2026-08-20T19:02:00+09:00","room":"RP","name":"마을 주민들","profile":"델타인","identity":"reviewed","type":"dialogue","body":"다들 딱히 해산하지 않았습니다!","characters":[]},{"id":"RP-0242910","time":"2026-08-20T19:03:00+09:00","room":"RP","name":"마을 주민들","profile":"델타인","identity":"reviewed","type":"dialogue","body":"토르번더러,\n\n\"얼굴에 그림 그린 놈이 귀상어인 척하기는….\"\n\"얌마, 귀상어가 아니고 고상.\"\n\"거상?\"\n\n하며 놀려대거나…","characters":[]},{"id":"RP-0242911","time":"2026-08-20T19:05:00+09:00","room":"RP","name":"마을 주민들","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"이러다가 뱃살 다 빠져서 홀쭉해지는 거 아닌가 몰러?\"\n\"이야, 산티아고. 자네 마누라가 좋아하겠구먼!\"\n\"무슨 소리여? 나 마누라 없는데.\"\n\"엄, 그럼 마누라를 만들 수 있겠구먼!\"\n\"나 한달 전에 이혼했는데? 그래서 쩌기 저 토팔까지 갔다왔잖여?\"","characters":[]},{"id":"RP-0242912","time":"2026-08-20T19:05:00+09:00","room":"RP","name":"마을 주민들","profile":"델타인","identity":"reviewed","type":"dialogue","body":"투덜거리긴 했네요.","characters":[]},{"id":"RP-0242913","time":"2026-08-20T19:06:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"그들의 농담따먹기에도 불구하고 토르번은 흡족한 듯 웃으며 검을 뽑았습니다.\n\n\"다들 잡담할 힘 남았으면 그만 떠들고 무기 챙겨서 따라오게. 이제 진짜로 싸우는 법을 알려줄테니까.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0242914","time":"2026-08-20T19:07:00+09:00","room":"RP","name":"마을 주민들","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"으익, 하브야! 저 얼굴에 낙서한 북부 놈이 이젠 우릴 아주 죽일라 그런다!\"","characters":[]},{"id":"RP-0242915","time":"2026-08-20T19:07:00+09:00","room":"RP","name":"마을 주민들","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"행님, 그래도 생긴 건 행님도 해적 같이 생겼잖습니까. 겁 내지 마십쇼!\"","characters":[]},{"id":"RP-0242916","time":"2026-08-20T19:08:00+09:00","room":"RP","name":"마을 주민들","profile":"델타인","identity":"reviewed","type":"dialogue","body":"어제 저녁에 페트라에게 속성으로 배운대로 한 명이 그물을, 한 명이 작살을 들었습니다.","characters":[]},{"id":"RP-0242917","time":"2026-08-20T19:09:00+09:00","room":"RP","name":"마을 주민들","profile":"델타인","identity":"reviewed","type":"dialogue","body":"그리고 션이 길드의 애송이들에게 그랬던 것처럼 토르번도 어부들을 신나게 쥐어패댔습니다.","characters":[]},{"id":"RP-0242918","time":"2026-08-20T19:09:00+09:00","room":"RP","name":"마을 주민들","profile":"델타인","identity":"reviewed","type":"dialogue","body":"이제야 션의 마음이 이해가 가나요? 근데 좀 더 비슷해졌네요.","characters":[]},{"id":"RP-0242919","time":"2026-08-20T19:10:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"자. 이게 찌르기라는 걸세.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0242920","time":"2026-08-20T19:10:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-7ba611cf90be"]},{"id":"RP-0242921","time":"2026-08-20T19:10:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"1일차 부터 그들의 밤은 아주 깁니다....!","characters":["P-7ba611cf90be"]},{"id":"RP-0242922","time":"2026-08-20T19:10:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-7ba611cf90be"]},{"id":"RP-0242923","time":"2026-08-20T19:10:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...good for you.","characters":[]}]};
